function reportsPage(d){const filter=(arr)=>arr.filter(x=>{const date=x.date||"";if(reportRange==="day")return date===today();if(reportRange==="week")return within(date,7);if(reportRange==="month")return date.slice(0,7)===today().slice(0,7);if(reportRange==="year")return date.slice(0,4)===today().slice(0,4);return true;});const sales=filter(d.sales),purchases=filter(d.purchases),expenses=filter(d.expenses),adjustments=filter(d.stock_adjustments),returns=filter(d.sales_returns);const {revenue,cogs,expenses:expenseTotal,stockLoss,gross,net}=profitSummary({sales,returns,expenses,adjustments}),investment=sum(purchases,x=>Number(x.total));const options=[["day","Today"],["week","Last 7 days"],["month","This month"],["year","This year"],["all","All time"]].map(x=>'<option value="'+x[0]+'" '+(reportRange===x[0]?"selected":"")+'>'+x[1]+'</option>').join("");return pageIntro("Business reports","Choose a period to review your business performance.")+'<div class="panel"><div class="panel-head"><div><h3>Performance summary</h3><p>Investment and profit are calculated from recorded transactions.</p></div><select id="reportRange" class="filters">'+options+'</select></div><div class="report-cards"><div class="report-card"><span>Investment</span><b>'+money(investment)+'</b></div><div class="report-card"><span>Sales</span><b>'+money(revenue)+'</b></div><div class="report-card"><span>Cost of goods sold</span><b>'+money(cogs)+'</b></div><div class="report-card"><span>Gross profit</span><b class="'+(gross>=0?"positive":"negative")+'">'+money(gross)+'</b></div><div class="report-card"><span>Expenses</span><b>'+money(expenseTotal)+'</b></div><div class="report-card"><span>Stock losses</span><b>'+money(stockLoss)+'</b></div><div class="report-card"><span>Net profit</span><b class="'+(net>=0?"positive":"negative")+'">'+money(net)+'</b></div></div><div class="form-actions" style="justify-content:flex-start;margin-top:16px"><button class="button secondary small" id="exportCsv">Export CSV</button></div></div><div class="panel"><h3 style="font-size:13px">Current stock value</h3><div class="stat-value">'+money(sum(d.products,p=>Number(p.stock||0)*Number(p.cost||0)))+'</div><p class="subtext">Based on the latest weighted-average cost per product.</p></div>';}
