document.addEventListener("click",async e=>{const page=e.target.closest("[data-page]");if(page){currentPage=page.dataset.page;$("#sidebar").classList.remove("open");await render();return;}const actionButton=e.target.closest("[data-action]");const action=actionButton?.dataset.action;if(action){if(action==="stock-adjustment"){addStockAdjustment();return;}if(action==="return-sale"){addSaleReturn(actionButton.dataset.id);return;}if(action==="supplier-ledger"){showSupplierLedger(actionButton.dataset.supplierId);return;}if(action==="business-profile"){editBusinessProfile();return;}if(action==="product-history"){showProductHistory(actionButton.dataset.id);return;}if(action==="supplier-payment"){addSupplierPayment(actionButton.dataset.supplierId);return;}if(action==="invoice"){showSaleInvoice(actionButton.dataset.id);return;}if(action==="edit-product"){editProduct(actionButton.dataset.id);return;}if(action==="delete-product"){deleteProduct(actionButton.dataset.id);return;}const customerId=actionButton.dataset.customerId;if(action==="ledger"){showCustomerLedger(customerId);return;}if(action==="payment"){addPayment(customerId);return;}({sale:addSale,product:addProduct,purchase:addPurchase,customer:addCustomer,expense:addExpense,supplier:addSupplier}[action])?.();}});
$("#closeModal").onclick=closeModal;$("#modal").addEventListener("click",e=>{if(e.target.id==="modal")closeModal();});$("#mobileMenu").onclick=()=>$("#sidebar").classList.toggle("open");
$("#pageContent").addEventListener("input",e=>{if(e.target.id==="productSearch"){const q=e.target.value.toLowerCase();$("#productsTable")?.querySelectorAll("tbody tr").forEach(row=>row.style.display=row.innerText.toLowerCase().includes(q)?"":"none");}});
$("#pageContent").addEventListener("change",e=>{if(e.target.id==="chartRange"){chartRange=e.target.value;render();}if(e.target.id==="reportRange"){reportRange=e.target.value;render();}});
$("#pageContent").addEventListener("click",e=>{if(e.target.id==="exportCsv")exportCSV();if(e.target.id==="backupData")downloadBackup();if(e.target.id==="chooseRestore")$("#restoreFile").click();});
$("#pageContent").addEventListener("change",async e=>{if(e.target.id==="restoreFile"){try{await restoreBackup(e.target.files[0]);}catch(err){toast(err.message||"Restore failed");}e.target.value="";}});
async function exportCSV(){const d=await data(),csv="\uFEFF"+buildAccountingCsv(d),url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download="karobaar-accounting-report.csv";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){try{db=await openDB();await render();if("serviceWorker"in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{});}catch(e){console.error(e);toast("Could not open local database. Please reload the app.");}}
init();